CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE closure_run(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,baseline_version text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','assessing','ready','submitted','accepted','rejected')),started_by uuid NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),submitted_by uuid,submitted_at timestamptz,UNIQUE(id,tenant_id));
CREATE TABLE closure_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,closure_run_id uuid NOT NULL,source_type text NOT NULL,source_path text NOT NULL,source_commit text,checksum text,evidence_class text NOT NULL,validation_status text NOT NULL DEFAULT 'pending',validated_by uuid,validated_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,closure_run_id,source_path,source_commit),FOREIGN KEY(closure_run_id,tenant_id) REFERENCES closure_run(id,tenant_id));
CREATE TABLE closure_finding(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,closure_run_id uuid NOT NULL,finding_type text NOT NULL,severity text NOT NULL,title text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open',source_evidence_ids jsonb NOT NULL DEFAULT '[]',UNIQUE(id,tenant_id),FOREIGN KEY(closure_run_id,tenant_id) REFERENCES closure_run(id,tenant_id));
CREATE TABLE finding_disposition(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,closure_finding_id uuid NOT NULL,classification text NOT NULL CHECK(classification IN('resolved','accepted_debt','deferred','prohibited','correction_required','authority_required')),owner_id uuid,authority_ref text,rationale text NOT NULL,decided_by uuid NOT NULL,decided_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,closure_finding_id),FOREIGN KEY(closure_finding_id,tenant_id) REFERENCES closure_finding(id,tenant_id));
CREATE TABLE readiness_check(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,closure_run_id uuid NOT NULL,criterion_key text NOT NULL,result text NOT NULL CHECK(result IN('passed','failed','conditional','unverified')),evidence_ids jsonb NOT NULL DEFAULT '[]',rationale text NOT NULL,reviewed_by uuid NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),UNIQUE(tenant_id,closure_run_id,criterion_key),FOREIGN KEY(closure_run_id,tenant_id) REFERENCES closure_run(id,tenant_id));
CREATE TABLE transition_constraint(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,closure_run_id uuid NOT NULL,consumer text NOT NULL,constraint_type text NOT NULL,contract_ref text NOT NULL,requirement text NOT NULL,status text NOT NULL DEFAULT 'active',UNIQUE(id,tenant_id),UNIQUE(tenant_id,closure_run_id,consumer,constraint_type,contract_ref),FOREIGN KEY(closure_run_id,tenant_id) REFERENCES closure_run(id,tenant_id));
CREATE TABLE freeze_recommendation(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,closure_run_id uuid NOT NULL,recommendation text NOT NULL CHECK(recommendation IN('recommend_freeze','conditional','do_not_freeze')),conditions jsonb NOT NULL DEFAULT '[]',rationale text NOT NULL,issued_by uuid NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),executive_decision text,executive_decided_by uuid,executive_decided_at timestamptz,UNIQUE(id,tenant_id),UNIQUE(tenant_id,closure_run_id),FOREIGN KEY(closure_run_id,tenant_id) REFERENCES closure_run(id,tenant_id));
CREATE TABLE closure_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,closure_run_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,tenant_id),FOREIGN KEY(closure_run_id,tenant_id) REFERENCES closure_run(id,tenant_id));
CREATE INDEX idx_closure_run_status ON closure_run(tenant_id,status); CREATE INDEX idx_closure_finding_open ON closure_finding(tenant_id,status,severity); CREATE INDEX idx_readiness_result ON readiness_check(tenant_id,closure_run_id,result); CREATE INDEX idx_closure_audit_time ON closure_audit(tenant_id,closure_run_id,occurred_at);
CREATE OR REPLACE FUNCTION prevent_closure_self_approval() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE submitter uuid; BEGIN SELECT submitted_by INTO submitter FROM closure_run WHERE id=NEW.closure_run_id AND tenant_id=NEW.tenant_id; IF submitter IS NOT NULL AND submitter=NEW.issued_by THEN RAISE EXCEPTION 'closure submitter cannot issue own freeze recommendation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_closure_self_approval BEFORE INSERT ON freeze_recommendation FOR EACH ROW EXECUTE FUNCTION prevent_closure_self_approval();
CREATE OR REPLACE FUNCTION protect_closure_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (TG_TABLE_NAME='closure_run' AND OLD.status IN('submitted','accepted','rejected')) OR (TG_TABLE_NAME='closure_evidence' AND OLD.validation_status='validated') OR (TG_TABLE_NAME='closure_finding' AND OLD.status='disposed') OR TG_TABLE_NAME IN('finding_disposition','readiness_check','transition_constraint','freeze_recommendation','closure_audit') THEN RAISE EXCEPTION 'closure evidence is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_closure_run_immutable BEFORE UPDATE OR DELETE ON closure_run FOR EACH ROW EXECUTE FUNCTION protect_closure_record(); CREATE TRIGGER trg_closure_evidence_immutable BEFORE UPDATE OR DELETE ON closure_evidence FOR EACH ROW EXECUTE FUNCTION protect_closure_record(); CREATE TRIGGER trg_closure_finding_immutable BEFORE UPDATE OR DELETE ON closure_finding FOR EACH ROW EXECUTE FUNCTION protect_closure_record(); CREATE TRIGGER trg_disposition_immutable BEFORE UPDATE OR DELETE ON finding_disposition FOR EACH ROW EXECUTE FUNCTION protect_closure_record(); CREATE TRIGGER trg_readiness_immutable BEFORE UPDATE OR DELETE ON readiness_check FOR EACH ROW EXECUTE FUNCTION protect_closure_record(); CREATE TRIGGER trg_transition_immutable BEFORE UPDATE OR DELETE ON transition_constraint FOR EACH ROW EXECUTE FUNCTION protect_closure_record(); CREATE TRIGGER trg_freeze_recommendation_immutable BEFORE UPDATE OR DELETE ON freeze_recommendation FOR EACH ROW EXECUTE FUNCTION protect_closure_record(); CREATE TRIGGER trg_closure_audit_immutable BEFORE UPDATE OR DELETE ON closure_audit FOR EACH ROW EXECUTE FUNCTION protect_closure_record();
ALTER TABLE closure_run ENABLE ROW LEVEL SECURITY; ALTER TABLE closure_evidence ENABLE ROW LEVEL SECURITY; ALTER TABLE closure_finding ENABLE ROW LEVEL SECURITY; ALTER TABLE finding_disposition ENABLE ROW LEVEL SECURITY; ALTER TABLE readiness_check ENABLE ROW LEVEL SECURITY; ALTER TABLE transition_constraint ENABLE ROW LEVEL SECURITY; ALTER TABLE freeze_recommendation ENABLE ROW LEVEL SECURITY; ALTER TABLE closure_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY closure_run_tenant ON closure_run USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY closure_evidence_tenant ON closure_evidence USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY closure_finding_tenant ON closure_finding USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY disposition_tenant ON finding_disposition USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY readiness_tenant ON readiness_check USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY transition_tenant ON transition_constraint USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY freeze_recommendation_tenant ON freeze_recommendation USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid); CREATE POLICY closure_audit_tenant ON closure_audit USING(tenant_id=(auth.jwt()->>'tenant_id')::uuid) WITH CHECK(tenant_id=(auth.jwt()->>'tenant_id')::uuid);
